 return {recordId,parentId,projectId:c.projectId,clipId:c.final.clipId,url:c.final.url,transcript:c.final.transcript,reviewGeneration:c.final.reviewGeneration};
}
function draftBinding({source,post}){
 check(post.parentId===source.parentId&&post.clipRecordId===source.recordId,'Draft linkage mismatch');
 check(['Instagram','YouTube'].includes(post.platform)&&post.body?.trim(),'Invalid clip draft');
 return {...post,reviewGeneration:source.reviewGeneration,approved:false,publishingStatus:'Draft'};
}
function prepareSchedule({row,owner,post,provider,accounts,now}){
 const {s,c}=approvedClip(row,owner,post.clipRecordId);
 check(post.parentId===c.parentId,'Post parent mismatch');
 const key='schedule|'+post.id,old=s.receipts[key];
 if(old){check(old.postId===post.id,'Receipt mismatch');return {action:old.state==='confirmed'?'already-scheduled':'reconcile',receipt:old};}
 check(post.approved===true&&post.publishingStatus==='Draft'&&!post.externalPostId,'Post not eligible');
 check(post.reviewGeneration===c.final.reviewGeneration,'Draft review stale');
 check(provider.id===c.projectId+'.'+c.final.clipId&&provider.renderAsVideoFile?.pending===false,'Provider identity/render mismatch');
 check(['Instagram','YouTube'].includes(post.platform),'Unsupported automatic platform');
 check(['Alex Woung','Alex Woung Raw'].includes(post.channel),'Unknown content channel');
 check(Number.isFinite(Date.parse(post.publishAt))&&Date.parse(post.publishAt)>now,'Future time required');
 const account=accounts.find(a=>a.id===post.accountId&&a.platform===post.platform&&a.channel===post.channel);
 check(account,'Exact connected destination required');
 check(post.platform!=='Instagram'||account.subAccountId,'Instagram subaccount required');
 const body={projectId:c.projectId,clipId:c.final.clipId,postAccountId:account.id,...(account.subAccountId?{subAccountId:account.subAccountId}:{}),postDetail:{title:post.title||'',custom:{description:post.body,privacy:'public'},mediaType:'video'},publishAt:new Date(post.publishAt).toISOString()};
 return {action:'persist-intent-first',key,expectedGeneration:s.generation,postId:post.id,recordId:c.id,reviewGeneration:c.final.reviewGeneration,body};
}
function persistScheduleIntent({row,owner,prepared}){
 const {s}=readLocked(row,owner);check(prepared.action==='persist-intent-first'&&s.generation===prepared.expectedGeneration&&!s.receipts[prepared.key],'Concurrent schedule intent');
 const n=copy(s);n.generation++;n.receipts[prepared.key]={state:'pending',postId:prepared.postId,recordId:prepared.recordId,reviewGeneration:prepared.reviewGeneration,body:prepared.body};
 return {expectedGeneration:s.generation,reviewLedger:JSON.stringify(n)};
}
function verifyScheduleIntent({row,owner,prepared}){
 const {s}=readLocked(row,owner),r=s.receipts[prepared.key];check(r?.state==='pending'&&r.postId===prepared.postId&&same(r.body,prepared.body),'Durable intent readback required');return prepared.body;
}
function providerOutcome({row,owner,key,response}){
 const {s}=readLocked(row,owner),r=s.receipts[key];check(r?.state==='pending','Pending receipt required');
 const rawId=response?.data?.scheduleId??response?.scheduleId;
 const id=typeof rawId==='string'&&rawId.trim()?rawId.trim():null;
 const n=copy(s);n.generation++;n.receipts[key]={...r,state:typeof id==='string'&&id.trim()?'confirmed':'uncertain',...(typeof id==='string'&&id.trim()?{scheduleId:id}:{})};
 // Failure/timeout never resets to Draft. Reconcile the provider before any retry.
 return {expectedGeneration:s.generation,reviewLedger:JSON.stringify(n),fields:id?{'Publishing Status':'Scheduled','External Post ID':id}:{'Publishing Status':'Publishing','Last Error':'Provider result uncertain. Reconcile before retry.'}};
}

'use strict';
const batchCheck=(v,m)=>{if(!v)throw Error(m)};
const channels={'Alex Woung':{Instagram:'691526d4d5e738e964057498',YouTube:'688ccc931ceff674de37516d'},'Alex Woung Raw':{Instagram:'6938e9b201af1ddee6ad025d',YouTube:'69152738d5e738e9640574bf'}};
function classify({row,owner,response}){
 const {r}=readLocked(row,owner);batchCheck(Array.isArray(response.records)&&!response.offset,'Complete approved draft page required');
 const legacy=[],managed=[];
 for(const post of response.records){const ids=post.fields?.['Content Clip'];if(!Array.isArray(ids)||!ids.length||!post.fields?.['Scheduled At'])continue;batchCheck(ids.length===1,'Ambiguous clip link');(r.clipIds.includes(ids[0])?managed:legacy).push(post)}
 return {legacy,managed};
}
function normalizePost(record,state){
 const f=record.fields??{},b=state.drafts?.[record.id];batchCheck(b,'Managed draft binding missing');
 const fingerprint={clipRecordId:f['Content Clip']?.[0],parentId:f['Parent Content']?.[0],platform:f.Platform,channel:String(f['Content Channel']??''),title:String(f['Draft Title']??''),body:String(f['Draft Body']??'')};
 batchCheck(JSON.stringify(fingerprint)===b.content,'Managed draft edited; review binding required');
 batchCheck(channels[fingerprint.channel]?.[fingerprint.platform],'Unsupported account/platform');
 return {...fingerprint,id:record.id,reviewGeneration:b.reviewGeneration,approved:f['Approval Status']==='Approved',publishingStatus:f['Publishing Status'],externalPostId:f['External Post ID']??'',publishAt:f['Scheduled At'],accountId:channels[fingerprint.channel][fingerprint.platform]};
}
function buildBatch({row,owner,records,providers,rawAccounts,now}){
 let working={...row};const {s}=readLocked(row,owner),prepared=[],reconcile=[];
 batchCheck(Array.isArray(rawAccounts),'Connected accounts required');
 batchCheck(new Set(records.map(r=>r.id)).size===records.length,'Duplicate draft');
 const accounts=[];for(const [channel,platforms] of Object.entries(channels))for(const [platform,id] of Object.entries(platforms)){const a=rawAccounts.find(x=>x.postAccountId===id);if(a)accounts.push({id,platform,channel,subAccountId:a.subAccountId})}
 for(const record of records){const state=readLocked(working,owner).s,post=normalizePost(record,state),clip=state.clips[post.clipRecordId],provider=providers.find(p=>p.id===clip?.projectId+'.'+clip?.final?.clipId);
  const plan=prepareSchedule({row:working,owner,post,provider:provider??{},accounts,now});
  if(plan.action!=='persist-intent-first'){reconcile.push({postId:post.id,action:plan.action,receipt:plan.receipt});continue;}
  const next=persistScheduleIntent({row:working,owner,prepared:plan});working.reviewLedger=next.reviewLedger;prepared.push(plan);
 }
 return {expectedGeneration:s.generation,reviewLedger:working.reviewLedger,prepared,reconcile};
}
function readbackBatch({row,owner,batch}){
 const {s}=readLocked(row,owner);batchCheck(s.generation===batch.expectedGeneration+batch.prepared.length,'Batch generation changed');
 return batch.prepared.map(p=>({key:p.key,postId:p.postId,body:verifyScheduleIntent({row,owner,prepared:p})}));
}
function outcomesBatch({row,owner,prepared,outcomes}){
 const s=readLocked(row,owner).s;batchCheck(outcomes.length===prepared.length&&new Set(outcomes.map(x=>x.key)).size===outcomes.length,'Outcome count/identity mismatch');
 let working={...row};const mirrors=[];
 for(const plan of prepared){const out=outcomes.find(x=>x.key===plan.key);batchCheck(out&&out.postId===plan.postId,'Outcome pairing mismatch');const result=providerOutcome({row:working,owner,key:plan.key,response:out.response});working.reviewLedger=result.reviewLedger;mirrors.push({recordId:plan.postId,fields:result.fields});}
 return {expectedGeneration:s.generation,reviewLedger:working.reviewLedger,mirrors};
}
if($input.first().json.owner!=='FREE')throw Error('Error unlock not confirmed');return [{json:{held:true,lockReleased:true,reviewRequired:true,noBlindRetry:true}}];
